"""Shared helpers used by every generator.

The two functions exported here let any generator script find the
output directory in a uniform way:

* :func:`out_dir` — the user-chosen build target (set by
  :class:`metaphysica.build.build` via the ``METAPHYSICA_OUT`` env var,
  defaults to the current working directory).
* :func:`autogen_dir` — the ``AutoGenerated/`` subdirectory under
  :func:`out_dir`, created on demand.
"""
from __future__ import annotations

import os
from pathlib import Path


def out_dir() -> Path:
    """Return the directory the build is writing into."""
    raw = os.environ.get("METAPHYSICA_OUT")
    if raw:
        return Path(raw).resolve()
    return Path.cwd().resolve()


def autogen_dir() -> Path:
    """Return ``out_dir() / "AutoGenerated"``, creating it if missing."""
    p = out_dir() / "AutoGenerated"
    p.mkdir(parents=True, exist_ok=True)
    return p


__all__ = ["out_dir", "autogen_dir"]
